sql:
SELECT CAST(SUM(CASE WHEN mp.msg_id IS NOT NULL THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM cchist.public.human_message AS hm
LEFT JOIN cchist.public.message_pattern_hit AS mp ON hm.msg_id = mp.msg_id;

